import sys

def main():
    lines = sys.stdin.read().strip().split('\n')
    if len(lines) < 3:
        print('no')
        return

    first_line = lines[0].strip()
    if not first_line:
        print('no')
        return

    first_line_parts = first_line.split()
    if len(first_line_parts) < 2:
        print('no')
        return

    rows = int(first_line_parts[0])
    cols = int(first_line_parts[1])

    elements_line = lines[1].strip()
    elements_part = elements_line.split()[0]
    elements = list(map(int, elements_part.split()))

    target = int(lines[2].strip())

    expected = rows * cols
    actual = len(elements)

    if actual == expected:
        matrix = [elements[i * cols:(i + 1) * cols] for i in range(rows)]
    else:
        matrix = []
        for i in range(rows):
            row_start = i * cols
            row_end = row_start + cols
            if row_end <= actual:
                matrix.append(elements[row_start:row_end])
            elif row_start < actual:
                matrix.append(elements[row_start:actual] + [0] * (row_end - actual))
            else:
                matrix.append([0] * cols)

    found = False
    for row in matrix:
        if target in row:
            found = True
            break

    print('yes' if found else 'no')

if __name__ == "__main__":
    main()
